actions.script:
const reg=ec.resource.script('component://mr-pass/screen/Marketing/Registrations.js'),marketing=reg.marketing
const page=marketing.base(publicPath,'showTicket')
const ref=marketing.param('ref')
const out=reg.call('getRegistration',resolvedSiteId,reg.reachOf(resolvedSiteId,ref,null),{showTicket:marketing.param('registrationId'),
    operationId:marketing.param('operationId')})
if(out.result?.registration?.ticket)reg.keepTicket(out.result.registration.ticket)
reg.back(page,{ref},out.error || null)

const reg=ec.resource.script('component://mr-pass/screen/Marketing/Registrations.js'),marketing=reg.marketing
const page=marketing.base(publicPath,'confirm')
const ref=marketing.param('ref')
const out=reg.call('getRegistration',resolvedSiteId,reg.reachOf(resolvedSiteId,ref,null),{confirm:'Y'})
reg.back(page,{ref},out.error || null)

const reg=ec.resource.script('component://mr-pass/screen/Marketing/Registrations.js'),marketing=reg.marketing
const page=marketing.base(publicPath,'cancel')
const ref=marketing.param('ref')
const out=reg.call('cancelRegistration',resolvedSiteId,reg.reachOf(resolvedSiteId,ref,null),{registrationIds:marketing.params('registrationId'),
    reason:marketing.param('reason'),confirm:marketing.param('confirm'),operationId:marketing.param('operationId')})
reg.back(page,{ref},out.error || null)

pre-actions.script:
// a link's token is read once, kept in the session, and the address replaced by the reservation's reference
const reg=ec.resource.script('component://mr-pass/screen/Marketing/Registrations.js'),marketing=reg.marketing
const token=marketing.param('token')
if(token){
    const found=reg.call('getRegistration',resolvedSiteId,{token},{})
    if(found.result){
        reg.keep(resolvedSiteId,found.result.registration.reference,token)
        sri.sendRedirectAndStopRender(String(publicPath)+marketing.query({ref:found.result.registration.reference}))
    }
}

actions.script:
const reg=ec.resource.script('component://mr-pass/screen/Marketing/Registrations.js'),marketing=reg.marketing
flash=marketing.take()
ticket=reg.takeTicket()
const ref=marketing.param('ref')
view=null;failure=null
const notAvailable={kind:'NotFound',message:ec.l10n.localize("This registration is not available. The link may have expired: open the latest one from your email.")}
const reach=ref?reg.reachOf(resolvedSiteId,ref,null):null
if(!reach)failure=notAvailable
else{
    const found=reg.call('getRegistration',resolvedSiteId,reach,{})
    if(found.error)failure=found.error.kind==='NotFound'?notAvailable:found.error
    else view=found.result.registration
}
if(view && view.limited){view=null;failure=notAvailable}
placeList=view?Array.from(view.places || []):[]
// the places the accepted terms' cancellation rule lets the buyer cancel online now (follow-up 1)
livePlaces=placeList.filter(p=>p.canCancel)
operationId=marketing.portal.operationId()
registerPath=String(publicPath).replace(/\/Registration$/,'/Register')
